import Foundation

/// 云厂商官方标识（PNG base64，保留品牌色与透明背景）。
enum ProviderLogoData {
    static let volcengine = ""
    static let tencent = ""
    static let huawei = ""
    static let qianfan = ""
    static let alibaba = ""

    static func base64(for provider: ProviderID) -> String? {
        switch provider {
        case .volcengine: return volcengine
        case .alibaba: return alibaba
        case .tencent: return tencent
        case .huawei: return huawei
        case .qianfan: return qianfan
        default: return nil
        }
    }
}